    "content": "from decimal import Decimal

def format_inr(paise):
    if paise < 0:
        sign = '-'
        paise = -paise
    else:
        sign = ''
    rupees = paise // 100
    paise %= 100
    formatted_paise = f'{paise:02d}'
    return f'{sign}₹{rupees},{formatted_paise}'
  }
}
